import os,fcntl,termios,struct,select,time,signal
class Probe:
 def __init__(self,args=(),cwd='/tmp/walk-fixture',env=None,w=80,h=24,exe='/workspace/executable'):
  master,slave=os.openpty(); r,out=os.pipe()
  fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',h,w,0,0))
  self.pid=os.fork()
  if self.pid==0:
   os.close(master);os.close(r);os.setsid();fcntl.ioctl(slave,termios.TIOCSCTTY,0)
   os.dup2(slave,0);os.dup2(slave,2);os.dup2(out,1)
   if slave>2:os.close(slave)
   if out>2:os.close(out)
   os.chdir(cwd)
   e=dict(os.environ,TERM='xterm-256color',COLORTERM='truecolor');e.update(env or {})
   os.execve(exe,[exe,*args],e)
  os.close(slave);os.close(out);self.master=master;self.out=r
 def read(self,wait=.15):
  time.sleep(wait);data=b''
  while select.select([self.master],[],[],0)[0]:
   try:
    s=os.read(self.master,65536)
    if not s:break
    data+=s
   except OSError:break
  return data
 def send(self,b,wait=.13):os.write(self.master,b);return self.read(wait)
 def close(self):
  try:os.kill(self.pid,signal.SIGTERM)
  except OSError:pass
  try:os.waitpid(self.pid,0)
  except OSError:pass
  os.close(self.master);os.close(self.out)
