"""A small, self-contained expression evaluator for the navigator's status line."""
import ast
import datetime
import math
import re


class ExpressionError(Exception):
    def __init__(self, message, pos=None, source=''):
        self.message, self.pos, self.source = message, pos, source
        super().__init__(message)

    def diagnostic(self):
        if self.pos is None:
            return self.message
        line = self.source.count('\n', 0, self.pos) + 1
        start = self.source.rfind('\n', 0, self.pos) + 1
        col = self.pos - start + 1
        text = self.source.split('\n')[line - 1]
        return f'{self.message} ({line}:{col})\n | {text}\n | ' + '.' * (col - 1) + '^'


def go_string(value):
    if value is None:
        return '<nil>'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
    if isinstance(value, float):
        if math.isnan(value):
            return 'NaN'
        if math.isinf(value):
            return '+Inf' if value > 0 else '-Inf'
        if value == int(value):
            return str(int(value))
        return format(value, '.15g')
    if isinstance(value, (list, tuple)):
        return '[' + ' '.join(go_string(x) for x in value) + ']'
    if isinstance(value, dict):
        return 'map[' + ' '.join(f'{go_string(k)}:{go_string(v)}' for k, v in sorted(value.items(), key=lambda p: str(p[0]))) + ']'
    return str(value)


def sprintf(fmt, *args):
    arg_index = 0
    pattern = re.compile(r'%(?:\[(\d+)\])?([-+# 0]*)(\d*)(?:\.(\d+))?([a-zA-Z%])')

    def replace(match):
        nonlocal arg_index
        index, flags, width, precision, verb = match.groups()
        if verb == '%':
            return '%'
        if index:
            arg_index = int(index) - 1
        if arg_index >= len(args):
            return '%!' + verb + '(MISSING)'
        val = args[arg_index]
        arg_index += 1
        try:
            if verb in 'sv':
                text = go_string(val)
                if precision:
                    text = text[:int(precision)]
            elif verb == 'q':
                import json
                text = json.dumps(go_string(val), ensure_ascii=False)
            elif verb in 'doxXb':
                text = format(int(val), {'d':'d','o':'o','x':'x','X':'X','b':'b'}[verb])
            elif verb in 'eEfFgG':
                spec = '.' + (precision if precision is not None else '6') + verb
                text = format(float(val), spec)
            elif verb == 't':
                text = go_string(bool(val))
            elif verb == 'T':
                text = ('bool' if isinstance(val, bool) else 'string' if isinstance(val, str) else
                        'int' if isinstance(val, int) else 'float64' if isinstance(val, float) else '<nil>' if val is None else '[]interface {}')
            elif verb == 'c':
                text = chr(int(val))
            else:
                text = '%!' + verb + '(' + go_string(val) + ')'
        except (ValueError, TypeError):
            text = '%!' + verb + '(string=' + go_string(val) + ')'
        if width:
            n = int(width)
            text = text.ljust(n) if '-' in flags else text.rjust(n, '0' if '0' in flags else ' ')
        return text

    result = pattern.sub(replace, str(fmt))
    if arg_index < len(args):
        result += '%!(EXTRA ' + ', '.join(('string=' if isinstance(x, str) else 'int=') + go_string(x) for x in args[arg_index:]) + ')'
    return result


BUILTINS = {
    'Sprintf': sprintf,
    'PadLeft': lambda s, n: str(s).rjust(max(0, int(n))),
    'PadRight': lambda s, n: str(s).ljust(max(0, int(n))),
    'len': len,
    'join': lambda xs, sep='': str(sep).join(go_string(x) for x in xs),
    'split': lambda s, sep: s.split(sep),
    'splitAfter': lambda s, sep: [p + sep for p in s.split(sep)[:-1]] + [s.split(sep)[-1]],
    'upper': lambda s: str(s).upper(),
    'lower': lambda s: str(s).lower(),
    'trim': lambda s, chars=None: str(s).strip(chars),
    'trimPrefix': lambda s, prefix: s[len(prefix):] if s.startswith(prefix) else s,
    'trimSuffix': lambda s, suffix: s[:-len(suffix)] if suffix and s.endswith(suffix) else s,
    'replace': lambda s, old, new: s.replace(old, new),
    'repeat': lambda s, n: s * max(0, int(n)),
    'hasPrefix': lambda s, p: s.startswith(p),
    'hasSuffix': lambda s, p: s.endswith(p),
    'string': go_string,
    'int': int,
    'float': float,
    'abs': abs,
    'ceil': math.ceil,
    'floor': math.floor,
    'round': round,
    'min': lambda *xs: min(xs[0] if len(xs) == 1 and isinstance(xs[0], list) else xs),
    'max': lambda *xs: max(xs[0] if len(xs) == 1 and isinstance(xs[0], list) else xs),
    'sum': sum,
    'mean': lambda xs: sum(xs) / len(xs),
    'first': lambda xs: xs[0] if xs else None,
    'last': lambda xs: xs[-1] if xs else None,
    'reverse': lambda xs: list(reversed(xs)),
    'sort': lambda xs, order='asc': sorted(xs, reverse=(order == 'desc')),
    'uniq': lambda xs: list(dict.fromkeys(xs)),
    'flatten': lambda xs: [y for x in xs for y in (x if isinstance(x, list) else [x])],
    'keys': lambda d: list(d.keys()),
    'values': lambda d: list(d.values()),
    'type': lambda x: 'string' if isinstance(x, str) else 'bool' if isinstance(x, bool) else 'int' if isinstance(x, int) else 'array' if isinstance(x, list) else 'nil' if x is None else 'unknown',
    'now': datetime.datetime.now,
    'get': lambda obj, key: obj.get(key) if isinstance(obj, dict) else obj[key],
    'toJSON': lambda x: __import__('json').dumps(x, separators=(',', ':')),
    'fromJSON': lambda x: __import__('json').loads(x),
}
LAMBDA_FUNCTIONS = {'map', 'filter', 'all', 'any', 'none', 'one', 'count', 'find', 'findLast', 'findIndex', 'findLastIndex', 'sortBy', 'groupBy', 'reduce'}
NAMES = set(BUILTINS) | LAMBDA_FUNCTIONS | {'current_file','files','Size','Mode','ModTime','Owner','true','false','nil','#','let','if','else'}


class Expression:
    _token = re.compile(r'''\s+|(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`[^`]*`)|(?:\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|(?:[\w$]+)|(?:\?\?|\?\.|==|!=|<=|>=|&&|\|\||\*\*|\.\.)|.''', re.S)
    precedence = {'|':1, '??':2, 'or':3, '||':3, 'and':4, '&&':4,
                  '==':5,'!=':5,'in':5,'not in':5,'contains':5,'startsWith':5,'endsWith':5,'matches':5,
                  '<':6,'>':6,'<=':6,'>=':6,'..':7,'+':8,'-':8,'*':9,'/':9,'%':9,'**':10}

    def __init__(self, source):
        self.source = source
        self.tokens = [(m.group(), m.start()) for m in self._token.finditer(source) if not m.group().isspace()]
        self.tokens.append(('', len(source)))
        self.i = 0
        self.locals = set()
        if not self.peek():
            self.error('unexpected token EOF', None)
        self.tree = self.parse(0)
        if self.peek():
            self.unexpected()
        self.check(self.tree)

    def error(self, msg, pos):
        raise ExpressionError(msg, pos, self.source)

    def peek(self):
        return self.tokens[self.i][0]

    def take(self):
        token = self.tokens[self.i]
        self.i += 1
        return token

    def expect(self, val):
        if self.peek() != val:
            self.unexpected()
        return self.take()

    def unexpected(self):
