        if not value:
            self.error('unexpected token EOF', None)
        kind = 'Identifier' if re.match(r'^\w', value) else 'Operator' if value in self.precedence else 'Bracket' if value in '()[]{}' else 'Operator'
        self.error(f'unexpected token {kind}("{value}")', pos)

    def parse(self, minimum=0):
