            left = ('list', vals, pos)
        elif tok == '{':
            left = ('lambda', self.parse(0), pos)
            self.expect('}')
        elif tok == 'let':
            name, npos = self.take()
            self.locals.add(name)
            self.expect('=')
            val = self.parse(0)
            self.expect(';')
            left = ('let', name, val, self.parse(0), pos)
        elif tok == 'if':
            cond = self.parse(0)
            self.expect('{'); yes = self.parse(0); self.expect('}')
            self.expect('else'); self.expect('{'); no = self.parse(0); self.expect('}')
            left = ('ternary', cond, yes, no, pos)
        elif tok[:1] in ('"', "'", '`'):
