            if match: keys.append(('unknown',None)); i += len(match.group()); continue
            if i+1 < len(s) and ord(s[i+1]) >= 32:
                keys.append(('alt-'+s[i+1],None)); i += 2; continue
            keys.append(('esc',None)); i += 1; continue
        if s[i] in CONTROLS:
            keys.append((CONTROLS[s[i]],None)); i += 1; continue
        if ord(s[i]) < 32:
            keys.append(('ctrl-'+chr(ord('a')+ord(s[i])-1),None)); i += 1; continue
        start = i
        while i < len(s) and ord(s[i]) >= 32 and s[i] not in ('\x7f',' '): i += 1
        keys.append(('text',s[start:i]))
    return keys


@dataclass
class PendingDelete:
    entry: Entry
    directory: str
    deadline: float
    index: int
    count: int = 5


class Navigator:
    def __init__(self,args,expression,input_fd):
        self.input_fd = input_fd
        self.expression = expression
        self.cwd = self.initial_cwd()
        self.original_cwd = self.cwd
        self.icons_on = '--icons' in args
        self.dir_only = '--dir-only' in args
        self.hide_hidden = '--hide-hidden' in args
        self.preview = '--preview' in args
        self.border = '--with-border' in args
        self.always_fuzzy = '--fuzzy' in args
        self.fuzzy = False
        self.query = ''
        self.help = False
        self.copied = ''
        self.marked = None
        self.pending = []
        self.selected = 0
        self.offset = 0
        self.files = []
        self.error = ''
        self.memory = {}
        self.quit = None
        self.need_resize = False
        self.palette = Palette()
        self.icons = Icons()
        self.screen_width, self.screen_height = self.window_size()
        self.renderer = Renderer(self.screen_width,self.screen_height)
        self.cols = 1; self.rows = 1; self.col_widths = [1]
        self.grid_width = 1
        self.cached_preview = {}
        self.editor = os.environ.get('WALK_EDITOR', os.environ.get('EDITOR','vi'))
        self.remove_command = os.environ.get('WALK_REMOVE_CMD', 'rm -rf')
        self.remove_default = 'WALK_REMOVE_CMD' not in os.environ
        self.open_commands = self.parse_open_commands(os.environ.get('WALK_OPEN_WITH',''))
        known = {'--icons','--dir-only','--hide-hidden','--preview','--with-border','--fuzzy'}
        path = next((a for a in args if a not in known),None)
        if path is not None:
            self.cwd = os.path.normpath(os.path.join(self.cwd,path))
            if self.cwd.startswith('//'): self.cwd = '/' + self.cwd.lstrip('/')
        self.load()

    @staticmethod
    def initial_cwd():
        try: cwd = os.getcwd()
        except OSError: cwd = os.environ.get('PWD','/')
        given = os.environ.get('PWD','')
        if given.startswith('/'):
            try:
                if os.path.samestat(os.stat(given),os.stat(cwd)): return given
            except OSError: pass
        return cwd

    def window_size(self):
        try:
            h,w,_,_ = struct.unpack('HHHH',fcntl.ioctl(2,termios.TIOCGWINSZ,b'\0'*8))
            return w or 80,h or 24
        except OSError:
            # The model still uses the input terminal, but the renderer has no width.
            try:
                h,w,_,_ = struct.unpack('HHHH',fcntl.ioctl(self.input_fd,termios.TIOCGWINSZ,b'\0'*8))
                return 0,h or 24
            except OSError: return 0,24

    @staticmethod
    def parse_open_commands(s):
        result = {}
        for part in s.split(','):
            if ':' in part:
                suffixes, command = part.split(':',1)
                for extension in suffixes.split('|'): result[extension] = command
        return result

    def entries(self,path):
        try:
            with os.scandir(path) as scan: es = [Entry(e) for e in scan]
            es.sort(key=lambda e:os.fsencode(e.name))
            if self.hide_hidden: es = [e for e in es if not e.name.startswith('.')]
            if self.dir_only: es = [e for e in es if e.isdir]
            removed = {d.entry.path for d in self.pending}
            es = [e for e in es if e.path not in removed]
            return es,''
        except OSError as exc:
            reason = os.strerror(exc.errno).lower()
            operation = 'readdirent' if exc.errno == errno.ENOTDIR and os.path.isfile(path) else 'open'
            return [],f'{operation} {path}: {reason}'

    def load(self, select_name=None):
        self.files,self.error = self.entries(self.cwd)
        if select_name is not None:
            self.selected = next((i for i,e in enumerate(self.files) if e.name == select_name),0)
        self.selected = min(max(self.selected,0),max(len(self.files)-1,0))
        self.layout()

    def display_name(self,e):
        s = e.name + ('/' if e.isdir else '')
        if self.icons_on: s = self.icons.for_entry(e) + ' ' + s
        return s.replace('\t','    ')

    def compute_layout(self,files,available,height):
        n = len(files)
        if not n: return 1,1,[0],0
        names = [self.display_name(e) for e in files]
        desired = max(min(4,math.ceil(n/10)), n//max(1,(height-1)//3),1)
        desired = min(n,desired)
        for number in range(desired,0,-1):
            rows = math.ceil(n/number)
            columns = math.ceil(n/rows)
            sizes = [max(width(x) for x in names[c*rows:(c+1)*rows]) for c in range(columns)]
            total = sum(sizes) + 4*(columns-1)
            if total <= available or number == 1: return columns,rows,sizes,total
        return 1,n,[available],available

    def status_text(self):
        if self.pending:
            pending = self.pending[-1]
            return self.palette.deleted(f'{pending.entry.name} deleted. (u)ndo {pending.count}')
        if self.copied: return self.palette.bar('copied: ' + self.copied)
        if self.expression and self.files:
            e = self.files[self.selected]
            env = {'current_file':e,'files':self.files,'Size':lambda:size_string(e.Size()),
                   'Mode':lambda:str(e.Mode()),'Owner':lambda:owner_string(e),
                   'ModTime':lambda:modification_string(e.stat.st_mtime if e.stat else 0)}
            try: result = go_string(self.expression.evaluate(env))
            except Exception as exc: result = str(exc)
            if result: return self.palette.bar(result)
        return ''

    def layout(self):
        effective_height = max(2,self.screen_height - (1 if self.status_text() else 0))
        self.cols,self.rows,self.col_widths,self.grid_width = self.compute_layout(self.files,self.screen_width or 80,effective_height)
        visible = max(1,self.screen_height-1-(1 if self.status_text() else 0))
        row = self.selected % self.rows
        if row < self.offset: self.offset = row
        elif row >= self.offset + visible: self.offset = row-visible+1
        self.offset = min(self.offset,max(0,self.rows-visible))

    def table(self,files,rows,widths,chosen=None,marked=None,offset=0,height=None):
        if not files: return box('No files')
        height = rows if height is None else min(rows-offset,height)
        cols = len(widths)
        result = []
        for row in range(offset,offset+height):
            chunks = []
            for col in range(cols):
                index = col*rows+row
                text = self.display_name(files[index]) if index < len(files) else ''
                text = pad(text,widths[col])
                if index == chosen: text = self.palette.selected(text,marked == files[index].path)
                chunks.append(text)
            result.append('    '.join(chunks))
        return result

    def header(self,limit):
        shown = self.cwd
        home = os.environ.get('HOME','')
        if home and shown.startswith(home): shown = '~'+shown[len(home):]
        q = '/' + self.query if self.fuzzy or self.query else ''
        shown = suffix(shown,max(0,limit-width(q)))
        return self.palette.bar(shown)+self.palette.search(q)

    def preview_lines(self,entry,available,height):
        if not entry: return []
        path = entry.path
        title = self.palette.bar(entry.name)
        try:
            actual = os.stat(path)
            if stat.S_ISDIR(actual.st_mode):
                files,error = self.entries(path)
                if error: content = box(error,True)
                elif not files: content = box('No files')
                else:
                    _,rows,sizes,_ = self.compute_layout(files,max(1,available),height)
                    content = self.table(files,rows,sizes,height=max(1,height-1))
            elif not stat.S_ISREG(actual.st_mode):
                content = box('No preview available')
            else:
                key = (path,actual.st_mtime_ns,actual.st_size)
                if key not in self.cached_preview:
                    with open(path,'rb') as f: data = f.read(1024*1024)
                    try: text = data.decode('utf-8')
                    except UnicodeError: text = None
                    if text is None or '\0' in text:
                        self.cached_preview[key] = box('No preview available')
                    else:
                        text = text.replace('\r\n','\n').replace('\t','    ')
                        self.cached_preview[key] = highlight(entry.name,text).split('\n')
                content = self.cached_preview[key]
        except OSError as exc:
            content = box(f'open {path}: {os.strerror(exc.errno).lower()}',True)
        return [title]+content[:max(0,height-1)]

    def view(self):
        if self.help: return [self.palette.bar('help'),'']+KEY_HELP.split('\n')+['','']
        self.layout()
        status = self.status_text()
        available_height = max(1,self.screen_height-(1 if status else 0))
        if self.error: listing = box(self.error,True)
        elif not self.files: listing = box('No files')
        else: listing = self.table(self.files,self.rows,self.col_widths,self.selected,self.marked,self.offset,max(1,available_height-1))
        if self.preview and self.files:
            list_width = max(width(s) for s in listing)
            main_width = max(list_width,width(os.path.basename(self.cwd.rstrip('/'))))
            main_width = min(main_width,self.screen_width or 80)
            main = [self.header(main_width)]+listing
            second = self.preview_lines(self.files[self.selected],max(1,(self.screen_width or 80)-main_width-2-(1 if self.border else 0)),available_height)
            second_width = max([width(s) for s in second]+[0])
            result = []
            for i in range(max(len(main),len(second))):
                a = pad(main[i] if i < len(main) else '',main_width)
                if self.border:
                    b = ' '+self.palette.border()+' ' if i < len(second) else '   '
                else: b = '  '
                c = pad(second[i] if i < len(second) else '',second_width)
                result.append(a+b+c)
        else:
            result = [self.header(self.screen_width or 80)]+listing
        if status: result.extend(status.split('\n'))
        # Views explicitly keep the top of the listing when height is limited.
        return [crop(s,self.screen_width or 80) for s in result[:self.screen_height]]

    def change_directory(self,path,select_name=None):
        self.memory[self.cwd] = self.selected
        self.cwd = os.path.normpath(path)
        self.selected = 0
        self.offset = 0
        self.query = ''; self.fuzzy = False
        self.marked = None
        self.copied = ''
        self.load(select_name)

    def move(self,key):
        n = len(self.files)
        if not n: return
        r = self.rows; old = self.selected; row = old%r; col = old//r
        if key == 'up': new = (old-1)%n
        elif key == 'down': new = (old+1)%n
        elif key == 'left':
            newcol = (col-1)%self.cols
            new = min(newcol*r+row,n-1)
        elif key == 'right':
            newcol = (col+1)%self.cols
            new = min(newcol*r+row,n-1)
        elif key in ('shift-up','pgup'): new = col*r
        elif key in ('shift-down','pgdown'): new = min((col+1)*r-1,n-1)
        elif key == 'shift-left': new = row
        elif key == 'shift-right': new = min((self.cols-1)*r+row,n-1)
        elif key == 'home': new = 0
        elif key == 'end': new = n-1
        else: return
        self.selected = new
        self.marked = None
        self.layout()

    @staticmethod
    def match_score(query,name):
        q = query.casefold(); s = name.casefold()
        if not q: return None
        indices = []; pos = 0
        for char in q:
            found = s.find(char,pos)
            if found < 0: return None
            indices.append(found); pos = found+1
        # Prefer adjacent matches and word starts; use length as a tiebreaker.
        gap = indices[-1]-indices[0]+1-len(q)
        boundary = indices[0] == 0 or s[indices[0]-1] in ' _-./'
        score = gap*20 + indices[0]*2 + len(s)*0.01 - (10 if boundary else 0)
        return score

    def search(self,text):
        self.query += text
        if not self.query: return
        best = None; chosen = self.selected
        for i,e in enumerate(self.files):
            score = self.match_score(self.query,e.name)
            if score is not None and (best is None or score < best): best,chosen = score,i
        self.selected = chosen
        self.marked = None
        self.layout()

    def delete(self):
        if not self.files: return
        e = self.files[self.selected]
        if self.marked != e.path:
            self.marked = e.path; return
        self.pending.append(PendingDelete(e,self.cwd,time.monotonic()+6,self.selected))
        self.files.pop(self.selected)
        self.selected = min(self.selected,max(0,len(self.files)-1))
        self.marked = None
        self.layout()

    def perform_delete(self,pending):
        try:
            if self.remove_default:
                if os.path.islink(pending.entry.path) or not os.path.isdir(pending.entry.path): os.unlink(pending.entry.path)
                else: shutil.rmtree(pending.entry.path)
            else:
                subprocess.run([self.remove_command,pending.entry.path],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,cwd=self.original_cwd)
        except (OSError,ValueError): pass

    def tick(self):
        now = time.monotonic(); changed = False
        for p in list(self.pending):
            count = max(0,math.ceil(p.deadline-now)-1)
            if count != p.count: p.count = count; changed = True
            if now >= p.deadline:
                self.pending.remove(p); self.perform_delete(p); changed = True
        return changed

    def undo(self):
        self.marked = None
        if not self.pending: return
        p = self.pending.pop()
        if p.directory == self.cwd:
            self.load(p.entry.name)

    def copy_path(self):
        self.copied = self.files[self.selected].path if self.files else self.cwd
        # Use a clipboard program only when one is available, without writing to stdout.
        programs = []
        if os.environ.get('WAYLAND_DISPLAY'): programs.append(['wl-copy'])
        if os.environ.get('DISPLAY'): programs.extend([['xclip','-selection','clipboard'],['xsel','--clipboard','--input']])
        for cmd in programs:
            if shutil.which(cmd[0]):
                try: subprocess.run(cmd,input=self.copied.encode(),stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=1)
                except (OSError,subprocess.TimeoutExpired): pass
                break

    def open_file(self,entry):
        ext = os.path.splitext(entry.name)[1].lstrip('.')
        command = self.open_commands.get(ext,self.editor)
        try: argv = shlex.split(command)
        except ValueError: return
        if not argv: return
        argv.append(entry.path)
        # Shelling out is only for the user's configured editor, never for navigation.
        if not shutil.which(argv[0]): return
        was_alt = self.renderer.alt
        write_output(ESC+'2K\r'+ESC+'?2004l'+ESC+'?25h'+ESC+'?1002l'+ESC+'?1003l'+ESC+'?1006l')
        if was_alt: self.renderer.leave_alt()
        try: termios.tcsetattr(self.input_fd,termios.TCSANOW,self.old_termios)
        except termios.error: pass
        try: subprocess.run(argv,stdin=self.input_fd,stdout=1,stderr=2,cwd=self.original_cwd)
        except OSError: pass
        try: tty.setraw(self.input_fd)
        except termios.error: pass
        write_output(ESC+'?25l'+ESC+'?2004h')
        if was_alt: self.renderer.enter_alt()
        self.renderer.lines = []; self.renderer.raw_view = None; self.renderer.force = True
        self.load(entry.name)

    def handle(self,key,text):
        previous_help = self.help
        self.help = False
        self.copied = ''
        if key == 'ctrl-c': self.quit = 2; return
        if key == 'esc': self.quit = 0; return
        if key == 'space':
            self.preview = not self.preview
            if self.preview: self.renderer.enter_alt()
            else: self.renderer.leave_alt()
            return
        search_mode = self.fuzzy or self.always_fuzzy
        if key in ('text','paste'):
            if search_mode:
                if text == '/' and not self.always_fuzzy:
                    self.fuzzy = False; self.query = ''; self.marked = None
                else: self.search(text)
                return
            commands = {'h':'left','j':'down','k':'up','l':'right','g':'shift-up','G':'shift-down'}
            if text in commands: self.move(commands[text]); return
            if text == 'q': self.quit = 0; return
            if text == '?': self.help = not previous_help; return
            if text == '/': self.fuzzy = True; self.query = ''; return
            if text == '.': self.hide_hidden = not self.hide_hidden; self.marked = None; self.load(); return
            if text == 'd': self.delete(); return
            if text == 'u': self.undo(); return
            if text == 'y': self.copy_path(); return
            self.marked = None
            return
        if key in ('up','down','left','right','shift-up','shift-down','shift-left','shift-right','home','end','pgup','pgdown'):
            self.move(key); return
        if key in ('backspace','ctrl-h'):
            self.marked = None
            if self.query: self.query = self.query[:-1]
            elif self.fuzzy: self.fuzzy = False
            else:
                path = self.cwd
                self.change_directory(os.path.dirname(path),os.path.basename(path))
            return
        if key == 'delete': self.delete(); return
        if key == 'enter':
            self.marked = None
            if self.files:
                entry = self.files[self.selected]
                if os.path.isdir(entry.path): self.change_directory(entry.path)
                else: self.open_file(entry)
            return
        self.marked = None

    def run(self):
        try: self.old_termios = termios.tcgetattr(self.input_fd); tty.setraw(self.input_fd)
        except termios.error:
            write_output(NO_TTY); return 2
        write_output(ESC+'?25l')
        if self.preview: self.renderer.enter_alt()
        write_output(ESC+'?2004h')
        self.renderer.render(self.view())
        def resized(signum,frame): self.need_resize = True
        def terminated(signum,frame): self.quit = 2
        signal.signal(signal.SIGWINCH,resized)
        signal.signal(signal.SIGTERM,terminated)
        signal.signal(signal.SIGINT,terminated)
        try:
            while self.quit is None:
                changed = False
                if self.need_resize:
                    self.need_resize = False
                    self.screen_width,self.screen_height = self.window_size()
                    self.renderer.width,self.renderer.height = self.screen_width,self.screen_height
                    self.renderer.force = True; self.renderer.raw_view = None
                    changed = True
                if self.tick(): changed = True
                ready,_,_ = select.select([self.input_fd],[],[],0.04)
                if ready:
                    try: data = os.read(self.input_fd,65536)
                    except OSError: self.quit = 2; break
                    if not data: self.quit = 2; break
                    if data == b'\x1b':
                        more,_,_ = select.select([self.input_fd],[],[],.025)
                        if more: data += os.read(self.input_fd,65536)
                    for key,text in decode_keys(data):
                        self.handle(key,text)
                        if self.quit is not None: break
                    changed = True
                if changed and self.quit is None: self.renderer.render(self.view())
            if self.quit == 0:
                for pending in self.pending: self.perform_delete(pending)
                self.pending.clear()
                # Preview exits back into the inline listing before printing the path.
                if self.renderer.alt:
                    self.preview = False
                    self.renderer.leave_alt()
                final = self.view()+['']
            else:
                for pending in self.pending: write_output('Was not deleted: '+pending.entry.path+'\n')
                final = self.view()+['']
            self.renderer.render(final)
            self.renderer.cleanup()
        finally:
            try: termios.tcsetattr(self.input_fd,termios.TCSANOW,self.old_termios)
            except termios.error: pass
        if self.quit == 0: write_output(self.cwd+'\n',1)
        return self.quit or 0


def main():
    expression = None
    if 'WALK_STATUS_BAR' in os.environ:
        text = os.environ['WALK_STATUS_BAR']
        try: expression = Expression(text)
        except ExpressionError as exc:
            address = '0xc00001a058' if text else '0xc000014070'
            write_output('panic: '+exc.diagnostic()+'\n\ngoroutine 1 [running]:\nmain.compile({'+address+', '+hex(len(text.encode()))+'})\n\t/workspace/status_bar.go:16 +0xc5\nmain.main()\n\t/workspace/main.go:71 +0x127\n')
            return 2
    args = sys.argv[1:]
    for arg in args:
        if arg in ('-v','--version'):
            write_output(VERSION+'\n',1); return 0
        if arg in ('-h','--help'):
            write_output(HELP); return 1
    fd = 0
    if not os.isatty(0):
        try: fd = os.open('/dev/tty',os.O_RDWR)
        except OSError: write_output(NO_TTY); return 2
    try:
        return Navigator(args,expression,fd).run()
    except BrokenPipeError:
        return 2
    finally:
        if fd != 0: os.close(fd)


if __name__ == '__main__':
    sys.exit(main())
