import tty
import unicodedata
from dataclasses import dataclass
from pathlib import Path

from walk_expr import Expression, ExpressionError, go_string
from walk_highlight import highlight

VERSION = 'v1.13.0'
KEY_HELP = '''    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help'''
HELP = '\n  walk ' + VERSION + '\n\n  Usage: walk [path]\n\n' + KEY_HELP + '''

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

'''
NO_TTY = '''panic: could not open a new TTY: open /dev/tty: no such device or address

