ESC = '\x1b['
RESET = ESC + '0m'
ANSI = re.compile(r'\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07]*(?:\x07|\x1b\\)')


def write_output(s, fd=2):
    data = s.encode('utf-8', 'replace') if isinstance(s, str) else s
    try:
        while data:
            count = os.write(fd, data)
            data = data[count:]
    except OSError:
        pass


def rune_width(c):
    if c in '\r\n\x00': return 0
    if c == '\t': return 4
    if unicodedata.combining(c) or unicodedata.category(c) in ('Mn','Me','Cf'): return 0
    if ord(c) < 32 or 0x7f <= ord(c) < 0xa0: return 0
    return 2 if unicodedata.east_asian_width(c) in ('W','F') else 1


def width(s):
    return max((sum(rune_width(c) for c in line) for line in ANSI.sub('', s).split('\n')), default=0)


def crop(s, limit):
    """Cut an ANSI string without discarding the closing color codes."""
    if limit < 0: return s
    result = []; count = 0; pos = 0; stopped = False
    while pos < len(s):
        if s[pos] == '\x1b':
            m = ANSI.match(s, pos)
            if m:
                result.append(m.group()); pos = m.end(); continue
        ch = s[pos]; pos += 1
        if ch == '\t':
            ch = '    '
        cw = sum(rune_width(c) for c in ch)
        if not stopped and count + cw <= limit:
            result.append(ch); count += cw
        else:
            stopped = True
    return ''.join(result)


def suffix(s, limit):
    if limit <= 0: return ''
    if width(s) <= limit: return s
    out = []; n = 0
    for c in reversed(s):
        cw = rune_width(c)
        if n + cw > limit: break
        out.append(c); n += cw
    return ''.join(reversed(out))


def pad(s, n):
    return s + ' ' * max(0, n - width(s))


class Palette:
    def __init__(self):
        env = os.environ
        if not os.isatty(2): self.profile = 0
        elif env.get('COLORTERM', '').lower() in ('truecolor', '24bit'): self.profile = 24
        elif '256color' in env.get('TERM', ''): self.profile = 256
        else: self.profile = 0
        self.main = env.get('WALK_MAIN_COLOR', '#825df2')

    @staticmethod
    def color256(rgb):
        best, score = 16, 10**10
        levels = [0,95,135,175,215,255]
        for n in range(16, 256):
            if n < 232:
                i = n - 16
                col = (levels[i//36], levels[(i//6)%6], levels[i%6])
            else: col = (8 + (n-232)*10,) * 3
            dist = sum((a-b)**2 for a,b in zip(rgb,col))
            if dist < score: best, score = n, dist
        return best

    def code(self, col, background=False):
        if not self.profile or col is None: return ''
        base = 48 if background else 38
        if isinstance(col, tuple): rgb = col
        elif re.fullmatch(r'#[0-9a-fA-F]{6}', str(col)):
            rgb = tuple(int(col[i:i+2],16) for i in (1,3,5))
        elif re.fullmatch(r'#[0-9a-fA-F]{3}', str(col)):
            rgb = tuple(int(c*2,16) for c in col[1:])
        else:
            try: n = int(col)
            except (ValueError,TypeError): return ''
            if not 0 <= n <= 255: return ''
            if n < 8: return str((40 if background else 30) + n)
            if n < 16: return str((100 if background else 90) + n - 8)
            return f'{base};5;{n}'
        if self.profile == 24: return f'{base};2;{rgb[0]};{rgb[1]};{rgb[2]}'
        return f'{base};5;{self.color256(rgb)}'

    def style(self, s, fg='#ffffff', bg=None):
        codes = [self.code(fg), self.code(bg,True)]
        codes = [x for x in codes if x]
        if not codes: return s.replace('\t','    ')
        # A colored multiline block resets at each physical line.
        prefix = ESC + ';'.join(codes) + 'm'
        return '\n'.join(prefix + line.replace('\t','    ') + RESET for line in s.split('\n'))

    def bar(self,s): return self.style(s,bg='#5c5c5c')
    def search(self,s): return self.style(s,bg='#499f1c')
    def selected(self,s,delete=False): return self.style(s,bg='#ff0000' if delete else self.main)
    def border(self): return self.style('│',fg=self.main)
    def deleted(self,s): return self.style(s,bg='#ff0000')


class FileMode(int):
    def __str__(self):
        v = int(self)
        chars = [(31,'d'),(30,'a'),(29,'l'),(28,'T'),(27,'L'),(26,'D'),(25,'p'),(24,'S'),(23,'u'),(22,'g'),(21,'c'),(20,'t'),(19,'?')]
        prefix = ''.join(c for b,c in chars if v & (1<<b)) or '-'
        return prefix + ''.join(c if v & (1 << (8-i)) else '-' for i,c in enumerate('rwxrwxrwx'))


def file_mode(st_mode):
    result = stat.S_IMODE(st_mode) & 0o777
    if stat.S_ISDIR(st_mode): result |= 1<<31
    if stat.S_ISLNK(st_mode): result |= 1<<27
    if stat.S_ISBLK(st_mode): result |= 1<<26
    if stat.S_ISCHR(st_mode): result |= (1<<26)|(1<<21)
    if stat.S_ISFIFO(st_mode): result |= 1<<25
    if stat.S_ISSOCK(st_mode): result |= 1<<24
    if st_mode & stat.S_ISUID: result |= 1<<23
    if st_mode & stat.S_ISGID: result |= 1<<22
    if st_mode & stat.S_ISVTX: result |= 1<<20
    return FileMode(result)


class FileTime:
    def __init__(self, seconds): self.seconds = seconds
    def Format(self, layout):
        t = time.localtime(self.seconds)
        replacements = {'2006':f'{t.tm_year:04}', 'January':time.strftime('%B',t),'Jan':time.strftime('%b',t),
                        'Monday':time.strftime('%A',t),'Mon':time.strftime('%a',t),'01':f'{t.tm_mon:02}',
                        '02':f'{t.tm_mday:02}','_2':f'{t.tm_mday:2}','15':f'{t.tm_hour:02}','03':f'{(t.tm_hour-1)%12+1:02}',
                        '04':f'{t.tm_min:02}','05':f'{t.tm_sec:02}','2006':str(t.tm_year),
                        'MST':time.strftime('%Z',t),'-0700':time.strftime('%z',t),'PM':time.strftime('%p',t)}
        return re.sub('|'.join(re.escape(s) for s in sorted(replacements,key=len,reverse=True)), lambda m:replacements[m.group()],layout)
    def Unix(self): return int(self.seconds)
    def Year(self): return time.localtime(self.seconds).tm_year
    def Month(self): return time.localtime(self.seconds).tm_mon
    def Day(self): return time.localtime(self.seconds).tm_mday
    def __str__(self): return self.Format('2006-01-02 15:04:05 -0700 MST')


class Entry:
    def __init__(self, entry):
        self.path, self.name = entry.path, entry.name
        try: self.stat = entry.stat(follow_symlinks=False)
        except OSError: self.stat = None
        self.isdir = bool(self.stat and stat.S_ISDIR(self.stat.st_mode))
    def Name(self): return self.name
    def IsDir(self): return self.isdir
    def Type(self): return FileMode(int(self.Mode()) & ~0o777)
    def Info(self): return self
    def Size(self): return self.stat.st_size if self.stat else 0
    def Mode(self): return file_mode(self.stat.st_mode) if self.stat else FileMode(0)
    def ModTime(self): return FileTime(self.stat.st_mtime if self.stat else 0)
    def Sys(self): return None
    def __str__(self): return self.name


def size_string(n):
    if n < 1024: return f'{n}B'
    unit = 0; val = float(n)
    units = ['B','KB','MB','GB','TB','PB','EB']
    while val >= 1024 and unit < len(units)-1:
        val /= 1024; unit += 1
    return f'{val:.1f}{units[unit]}'


def modification_string(seconds):
    t = time.localtime(seconds)
    tail = f'{t.tm_hour:02}:{t.tm_min:02}' if t.tm_year == time.localtime().tm_year else str(t.tm_year)
    return time.strftime('%b',t) + ' ' + str(t.tm_mday) + ' ' + tail


def owner_string(entry):
    if not entry.stat: return ''
    uid, gid = entry.stat.st_uid, entry.stat.st_gid
    try: user = pwd.getpwuid(uid).pw_name
    except KeyError: user = str(uid)
    try: group = grp.getgrgid(gid).gr_name
    except KeyError: group = str(gid)
    return user + ' ' + group


class Icons:
    def __init__(self):
        self.types = {}; self.patterns = []
        try:
            with open(Path(__file__).resolve().parent / 'etc' / 'icons',encoding='utf-8') as f:
                for line in f:
                    if not line.strip() or line.lstrip().startswith('#'): continue
                    try: parts = shlex.split(line,comments=True)
                    except ValueError: continue
                    if len(parts) < 2: continue
                    pattern, symbol = parts[:2]
                    if '*' in pattern or '.' in pattern or len(pattern) > 2: self.patterns.append((pattern,symbol))
                    else: self.types[pattern] = symbol
        except OSError:
            self.types = {'di':'','ex':'','fi':'','pi':'p','so':'s','bd':'b','cd':'c'}
        # Last matching line in the configuration takes precedence.
        self.patterns.reverse()

    def for_entry(self,e):
        if e.isdir: return self.types.get('di','')
        for pattern, symbol in self.patterns:
            if fnmatch.fnmatchcase(e.name,pattern): return symbol
        mode = e.stat.st_mode if e.stat else 0
        if mode & 0o111: kind = 'ex'
        elif stat.S_ISFIFO(mode): kind = 'pi'
        elif stat.S_ISSOCK(mode): kind = 'so'
        elif stat.S_ISBLK(mode): kind = 'bd'
        elif stat.S_ISCHR(mode): kind = 'cd'
        else: kind = 'fi'
        return self.types.get(kind,'')


def box(message, error=False):
    lines = message.split('\n')
    w = max((width(s) for s in lines),default=0)
    # Error boxes have a wider rule than their message line.
    top_width = w + (4 if error else 2)
    return ['╭' + '─' * top_width + '╮'] + ['│ ' + pad(s,w) + ' │' for s in lines] + ['╰' + '─' * top_width + '╯']


class Renderer:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.lines = []
        self.alt = False
        self.force = False
        self.raw_view = None

    def move(self,n,code):
        return ESC + (str(n) if n != 1 else '') + code if n > 0 else ''

    def enter_alt(self):
        if self.alt: return
        write_output(ESC+'?1049h'+ESC+'2J'+ESC+'H'+ESC+'?25l')
        self.alt = True; self.force = True; self.raw_view = None

    def leave_alt(self):
        if not self.alt: return
        write_output(ESC+'?1049l'+ESC+'?25l')
        self.alt = False; self.force = True; self.raw_view = None

    def render(self, lines, force=False):
        raw_view = '\n'.join(lines)
        if self.raw_view == raw_view and not force and not self.force: return
        self.raw_view = raw_view
        # Terminal-height clipping is performed before writing, not by scrolling.
        new = lines[-self.height:] if self.height and len(lines) > self.height else list(lines)
        out = ''
        if self.alt: out += ESC+'H'
        elif self.lines: out += self.move(len(self.lines)-1,'A')
        if not self.lines or self.force: out += '\r'
        for i, line in enumerate(new):
            if not (force or self.force) and i < len(self.lines) and line == self.lines[i]:
                if i < len(new)-1: out += '\n'
                continue
            text = crop(line,self.width) if self.width > 0 else line
            out += text
            if self.width and width(text) < self.width: out += ESC+'K'
            if i < len(new)-1: out += '\r\n'
        if len(self.lines) > len(new): out += ESC+'J'
        if self.alt: out += ESC + str(len(new)) + ';H'
        else: out += ESC + (str(self.width) if self.width > 0 else '') + 'D'
        write_output(out)
        self.lines = new
        self.force = False

    def cleanup(self):
        write_output(ESC+'2K\r'+ESC+'?2004l'+ESC+'?25h'+ESC+'?1002l'+ESC+'?1003l'+ESC+'?1006l')
        if self.alt:
            write_output(ESC+'?1049l'+ESC+'?25h')
            self.alt = False


# CSI and SS3 keys understood by common VT-compatible terminals.
KEY_SEQUENCES = {
    '\x1b[A':'up','\x1b[B':'down','\x1b[C':'right','\x1b[D':'left',
    '\x1bOA':'up','\x1bOB':'down','\x1bOC':'right','\x1bOD':'left',
    '\x1b[H':'home','\x1b[F':'end','\x1bOH':'home','\x1bOF':'end',
    '\x1b[1~':'home','\x1b[4~':'end','\x1b[7~':'home','\x1b[8~':'end',
    '\x1b[3~':'delete','\x1b[5~':'pgup','\x1b[6~':'pgdown','\x1b[Z':'shift-tab',
    '\x1b[1;2A':'shift-up','\x1b[1;2B':'shift-down','\x1b[1;2C':'shift-right','\x1b[1;2D':'shift-left',
    '\x1b[a':'shift-up','\x1b[b':'shift-down','\x1b[c':'shift-right','\x1b[d':'shift-left',
    '\x1b[1;5A':'ctrl-up','\x1b[1;5B':'ctrl-down','\x1b[1;5C':'ctrl-right','\x1b[1;5D':'ctrl-left',
}
CONTROLS = {'\x03':'ctrl-c','\r':'enter','\n':'ctrl-j','\x7f':'backspace','\x08':'ctrl-h','\t':'tab','\x1b':'esc',' ':'space'}


def decode_keys(data):
    s = data.decode('utf-8','replace'); keys = []; i = 0
    while i < len(s):
        if s.startswith('\x1b[200~',i):
            end = s.find('\x1b[201~',i+6)
            if end < 0: end = len(s)
            keys.append(('paste',s[i+6:end])); i = min(end+6,len(s)); continue
        if s[i] == '\x1b':
            found = False
            for sequence,key in sorted(KEY_SEQUENCES.items(),key=lambda p:len(p[0]),reverse=True):
                if s.startswith(sequence,i): keys.append((key,None)); i += len(sequence); found = True; break
            if found: continue
            match = re.match(r'\x1b\[[0-?]*[ -/]*[@-~]',s[i:])
            if match: keys.append(('unknown',None)); i += len(match.group()); continue
            if i+1 < len(s) and ord(s[i+1]) >= 32:
                keys.append(('alt-'+s[i+1],None)); i += 2; continue
            keys.append(('esc',None)); i += 1; continue
        if s[i] in CONTROLS:
            keys.append((CONTROLS[s[i]],None)); i += 1; continue
        if ord(s[i]) < 32:
            keys.append(('ctrl-'+chr(ord('a')+ord(s[i])-1),None)); i += 1; continue
        start = i
        while i < len(s) and ord(s[i]) >= 32 and s[i] not in ('\x7f',' '): i += 1
        keys.append(('text',s[start:i]))
    return keys


